function check(input, actual, expected) {
  if (!Array.isArray(actual) || actual.length !== expected.length) return false;
  const last = expected.length - 1;
  const forward = actual.every((value, i) => value === expected[i]);
  const backward = actual.every((value, i) => value === expected[last - i]);
  return forward || backward;
}

