function validate([adjacentPairs]) {
  if (!Array.isArray(adjacentPairs) || adjacentPairs.length < 1 || adjacentPairs.length > 99999) return 'adjacentPairs needs 1 to 10^5 - 1 pairs.';
  const graph = new Map();
  for (const pair of adjacentPairs) {
    if (!Array.isArray(pair) || pair.length !== 2) return 'Each pair holds exactly two values.';
    if (pair.some(v => !Number.isInteger(v) || v < -100000 || v > 100000)) return 'Values are whole numbers from -10^5 to 10^5.';
    if (pair[0] === pair[1]) return 'A value cannot be its own neighbour.';
    for (const [a, b] of [pair, [pair[1], pair[0]]]) {
      if (!graph.has(a)) graph.set(a, []);
      graph.get(a).push(b);
    }
  }
  if (graph.size !== adjacentPairs.length + 1) return 'The pairs must use exactly n distinct values for n - 1 pairs.';
  for (const neighbors of graph.values()) if (neighbors.length > 2) return 'A value can have at most two neighbours.';
  const start = adjacentPairs[0][0];
  const seen = new Set([start]);
  const stack = [start];
  while (stack.length) for (const next of graph.get(stack.pop())) if (!seen.has(next)) { seen.add(next); stack.push(next); }
  if (seen.size !== graph.size) return 'The pairs must chain into one single array.';
  return null;
}

