function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const n = size === 'large' ? int(1500, 2000) : int(2, 8);
  const span = size === 'large' || rand() < 0.4 ? 100000 : 10;
  const used = new Set();
  const nums = [];
  while (nums.length < n) {
    const value = int(-span, span);
    if (!used.has(value)) {
      used.add(value);
      nums.push(value);
    }
  }
  const pairs = [];
  for (let i = 0; i + 1 < n; i++) pairs.push(rand() < 0.5 ? [nums[i], nums[i + 1]] : [nums[i + 1], nums[i]]);
  for (let i = pairs.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [pairs[i], pairs[j]] = [pairs[j], pairs[i]];
  }
  return [pairs];
}
